const staticData = $getWorkflowStaticData('global');

let config;
try {
  config = $('설정값 (필수 입력)').first().json;
} catch (e) {
  config = null;
}
const item = $input.first().json;
const accountId = (config && config.account_id) || item.account_id || item.threads_user_id || 'default';

if (!staticData.tokens) staticData.tokens = {};

if (!staticData.tokens[accountId] && staticData.access_token) {
  staticData.tokens[accountId] = staticData.access_token;
}

if (!staticData.tokens[accountId]) {
  throw new Error(`[${accountId}] 토큰이 없습니다. n8n에서 이 노드를 대상으로 1회 수동 시딩이 필요합니다 (staticData.tokens.${accountId}).`);
}

return [{ json: { access_token: staticData.tokens[accountId], account_id: accountId } }];

let productInfo;
try {
  productInfo = $('상품 정보 입력').first().json;
} catch (e) {
  try {
    productInfo = $('상품 정보 입력 (자동)').first().json;
  } catch (e2) {
    productInfo = $('상품 정보 입력 (시트)').first().json;
  }
}

const prompt = `다음 쿠팡 상품 정보를 바탕으로 스레드(Threads)에 올릴 후킹형 게시물 본문을 작성해줘.

[중요] 경제적 이해관계 표시 문구("이 게시물은 쿠팡 파트너스...")는 네가 쓰지 마. 그 문구는 별도 시스템이 게시물 맨 앞에 자동으로 붙인다. 너는 오직 후킹 본문만 작성한다.

[톤앤매너 - 가장 중요]
1. 반드시 반말로 작성할 것. 단, 무례하거나 건방지게 들리지 않고 친한 친구에게 다정하게 알려주듯 부드럽고 다정한 반말 톤으로 쓸 것 (하대하는 명령조 금지)
2. 광고 카피처럼 상품을 나열식으로 설명하지 말고, 친한 친구/지인한테만 살짝 귀홤해주는 듯한 편안한 대화체로 쓸 것 (예시: "있지,", "나만 알기 아까워서 알려주는거든", "이거 아직 모르는 사람 많을걸" 같은 친밀한 표현 활용)
3. [매우 중요] 첫 문장을 문맥 없이 뜸금없는 감탄사나 표현(예: "역시나", "그거 알아?" 단독 사용 등)으로 시작하지 말 것. 대신 상대방이 공감할 만한 구체적인 상황이나 질문으로 자연스럽게 시작할 것 (예시: "~할 때마다 불편했던 적 있지?", "~때마다 귀찮았던 거 있지 않아?")
3-1. [스레드 알고리즘 대응 - 첫 줄이 가장 중요] 첫 문장은 가능한 한 물음표로 끓나는 질문형으로 작성할 것. 스레드 알고리즘은 첫 줄에서 스크롤을 멈추는 비율을 가장 먼저 보기 때문에, 공감형 상황 제시 + 질문형 어미 조합을 최우선으로 할 것.
4. [매우 중요] 절대 1인칭으로 상품을 직접 체험한 것처럼 단정하지 말 것. 아래 표현은 절대 사용 금지:
   - "~써보니", "~써봐는데", "~써본 결과", "~사용해보니" (직접 체험 단정)
   - "~하더라", "~하더라고" (회상형 어미 - 직접 목격/경험했다는 뉴앙스라 마찬가지로 금지)
   대신 "~하대", "~한다던데", "~하다던데" 같은 전언(hearsay)형 표현이나, "이런 고민 있지 않았어?", "~한 사람 많을걸" 같은 공감형/추측형 표현만 사용할 것
5. "나만 모르면 손해 볼 것 같은" 느낌을 주는 후킹 요소를 포함할 것

[작성 규칙]
6. 제휴 링크 상품에 대한 관심을 자연스럽게 유도하는 내용으로 작성할 것. 상품명이나 핵심 기능/장점은 숨기지 말고 자연스럽게 드러낼 것 — 정체를 의도적으로 숨기는 클릭베이트 방식은 스레드 알고리즘이 노출 억제 대상으로 분류할 위험이 있으므로 쓰지 말 것.
6-1. 대신 "이런 상황에 이게 왜 좋은지", "어떤 점이 편한지" 같은 공감 포인트로 흥미를 끌 것 (정체 은폐가 아니라 공감/후킹으로 관심 유도).
6-2. [필수] 마지막 문장은 읽는 사람의 진짜 의견이나 비슷한 경험을 묻는 질문형 한 문장으로 작성할 것 (예: 비슷한 고민 있었는지, 어떻게 해결했는지, 써본 적 있는지 등 직접적인 질문). "팔로우해줘", "팔로우 해두면 편함" 같은 팔로우 언급이나 "구매는 댓글 링크 클릭" 같은 직접적 상업 문구는 절대 쓰지 말 것 — 팔로우 유도나 상업적 문구는 스레드 알고리즘이 follow-bait·광고성 콘텐츠로 감지해 노출을 억제함. 매번 다른 질문으로 자연스럽게 쓸 것 (특정 예문을 그대로 반복하지 말 것).
7. "최고", "최저가", "1등", "무조건" 등 객관적으로 입증하기 어려운 과장 표현은 쓰지 말 것
8. 문장이 자연스럽고 문법적으로 말이 되도록 작성할 것 (어색하거나 의미가 불분명한 표현 금지). 반드시 완결된 문장으로 끝낼 것 (문장이 중간에 끓기지 않도록 주의)
9. [필수] 이모지를 정확히 1~2개 반드시 포함할 것 (이모지가 하나도 없으면 안 됨). 줄바꿈도 적절히 사용해 가독성을 높일 것
10. 전체 내용은 공백 포함 230바이트 이내로 작성할 것 (한글 기준 약 68~72자, 이모지·영문 혼용 시 그보다 적은 글자 수)
11. [필수] 응답은 오직 JSON 객체 하나만 출력할 것. 사고 과정, 풀이 설명, 코드블록 표시(백틱) 등 그 어떤 부가 텍스트도 절대 출력하지 말 것. 첫 글자부터 반드시 { 로 시작해야 함:
{"post_text": "여기에 후킹 본문만, 경제적 이해관계 문구는 절대 포함하지 않음", "topic_tag": "이 상품을 대표하는 카테고리 단어 1개 (예: 청소, 주방, 뷰티, 인테리어 등). 반드시 띄어쓰기·마침표·특수문자 없이 한글 또는 영문 단어 하나로, #은 붙이지 말 것"}

[상품명]
${productInfo.product_title}

[상품 설명]
${productInfo.product_desc}`;

return [{
  json: {
    ai_request: {
      model: 'nvidia/nemotron-3-ultra-550b-a55b',
      messages: [
        { role: 'system', content: 'detailed thinking off. Never output reasoning, explanation, or markdown code fences. Output must start with { and be valid JSON only.' },
        { role: 'user', content: prompt }
      ],
      max_tokens: 900,
      temperature: 0.9,
      chat_template_kwargs: { enable_thinking: false }
    }
  }
}];

const DISCLOSURE = '이 게시물은 쿠팡 파트너스 활동의 일환으로, 이에 따른 일정액의 수수료를 제공받습니다.';

const PRICE_POINTER_POOL = [
  '가격이랑 링크는 댓글에 있음',
  '정확한 가격이랑 링크는 댓글 확인',
  '가격은 댓글에 적어둠',
  '자세한 가격이랑 링크는 댓글에',
  '가격이랑 구매 링크는 댓글에 있음'
];

const LINK_ONLY_POINTER_POOL = [
  '링크는 댓글에 있음',
  '구매 링크는 댓글 확인',
  '자세한 건 댓글 링크에서',
  '링크는 댓글에 따로 적어둠'
];

const PRICE_TEASE_POOL = [
  '가격 보고 나도 좀 놀람',
  '이 가격에 이 정도면 나쁘지 않은 듯',
  '가격표 보면 왜 인기인지 알 듯',
  '혹시 몰라서 가격도 같이 적어둠',
  '가격 확인하고 필요하면 링크 눌러봐'
];

const GENERIC_TEASE_POOL = [
  '궁금하면 링크 눌러봐',
  '필요하면 아래 링크로 확인해봐',
  '관심있으면 링크로 구경해봐',
  '자세한 건 링크에서 볼 수 있음'
];

function pick(pool) {
  return pool[Math.floor(Math.random() * pool.length)];
}

function sanitizeTopicTag(raw) {
  if (!raw) return '생활꿀템';
  let t = String(raw).trim().replace(/^#/, '').replace(/[\s.&]/g, '');
  if (!t) return '생활꿀템';
  return t.slice(0, 50);
}

let productInfo;
let isSheetSource = false;
try {
  productInfo = $('상품 정보 입력').first().json;
} catch (e) {
  try {
    productInfo = $('상품 정보 입력 (자동)').first().json;
  } catch (e2) {
    productInfo = $('상품 정보 입력 (시트)').first().json;
    isSheetSource = true;
  }
}
const tokenInfo = $('현재 토큰 불러오기').first().json;

let config;
try {
  config = $('설정값 (필수 입력)').first().json;
} catch (e) {
  config = null;
}
const threadsUserId = (config && config.threads_user_id) || productInfo.threads_user_id;
const accountId = (config && config.account_id) || productInfo.account_id || '';

let storyText;
let rawTopicTag = null;
if (productInfo.fixed_post_text) {
  storyText = productInfo.fixed_post_text;
} else {
  let aiResponse;
  try {
    aiResponse = $('스토리텔링 생성 (재시도)').first().json;
  } catch (e) {
    aiResponse = $('스토리텔링 생성 (NVIDIA API)').first().json;
  }
  const messageContent = aiResponse.choices && aiResponse.choices[0] && aiResponse.choices[0].message
    ? aiResponse.choices[0].message.content
    : null;
  const finishReason = aiResponse.choices && aiResponse.choices[0] ? aiResponse.choices[0].finish_reason : null;

  if (!messageContent) {
    throw new Error('NVIDIA API 응답에서 텍스트를 찾을 수 없습니다. 응답: ' + JSON.stringify(aiResponse));
  }

  let jsonSlice = messageContent.trim();
  const firstBrace = jsonSlice.indexOf('{');
  const lastBrace = jsonSlice.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    jsonSlice = jsonSlice.slice(firstBrace, lastBrace + 1);
  }

  jsonSlice = jsonSlice.replace(/\\\s+([nrtbf"\\\\\/])/g, '\\\\$1');
  jsonSlice = jsonSlice.replace(/\\(?!["\\\\\/bfnrtu])/g, '');

  try {
    const parsed = JSON.parse(jsonSlice);
    storyText = parsed.post_text;
    rawTopicTag = parsed.topic_tag;
  } catch (e) {
    throw new Error('NVIDIA 응답이 유효한 JSON이 아닙니다 (finish_reason=' + finishReason + '). 모델이 사고 과정을 출력했거나 응답이 잘렸을 가능성이 큽니다. 원문(300자): ' + messageContent.slice(0, 300));
  }

  if (!storyText) {
    throw new Error('post_text를 추출하지 못했습니다. 원문: ' + jsonSlice.slice(0, 300));
  }
}

storyText = storyText.split(DISCLOSURE).join('').trim();

const hasPrice = !!productInfo.price;
const pointer = hasPrice ? pick(PRICE_POINTER_POOL) : pick(LINK_ONLY_POINTER_POOL);
const postText = `${storyText}\n\n${pointer}`;

if (postText.length > 480) {
  throw new Error('생성된 post_text가 너무 깁니다 (' + postText.length + '자). Threads 500자 제한 초과 위험으로 게시를 중단합니다: ' + postText.slice(0, 200));
}

const priceLine = hasPrice ? `현재 가격: ${productInfo.price}\n` : '';
const tease = hasPrice ? pick(PRICE_TEASE_POOL) : pick(GENERIC_TEASE_POOL);
const commentText = `${DISCLOSURE}\n\n${priceLine}${tease}\n${productInfo.affiliate_link}`;
const topicTag = sanitizeTopicTag(rawTopicTag);

return [{
  json: {
    post_text: postText,
    comment_text: commentText,
    access_token: tokenInfo.access_token,
    threads_user_id: threadsUserId,
    account_id: accountId,
    affiliate_link: productInfo.affiliate_link,
    image_url: productInfo.image_url || '',
    is_sheet_source: isSheetSource,
    topic_tag: topicTag
  }
}];

const staticData = $getWorkflowStaticData('global');
const item = $input.first().json;
const accountId = item.account_id || item.threads_user_id || 'default';

if (!staticData.tokens) staticData.tokens = {};

if (!staticData.tokens[accountId] && staticData.access_token) {
  staticData.tokens[accountId] = staticData.access_token;
}

if (!staticData.tokens[accountId]) {
  throw new Error(`[${accountId}] 토큰이 없습니다. n8n에서 이 노드를 대상으로 1회 수동 시딩이 필요합니다 (staticData.tokens.${accountId}).`);
}

return [{ json: { access_token: staticData.tokens[accountId], account_id: accountId } }];

const staticData = $getWorkflowStaticData('global');
const response = $input.first().json;
const accountId = $('현재 토큰 불러오기 (갱신용)').first().json.account_id || 'default';

if (!response.access_token) {
  throw new Error(`[${accountId}] 토큰 갱신 응답에 access_token이 없습니다. 응답: ` + JSON.stringify(response));
}

if (!staticData.tokens) staticData.tokens = {};
staticData.tokens[accountId] = response.access_token;
if (!staticData.refreshed_at) staticData.refreshed_at = {};
if (!staticData.expires_at) staticData.expires_at = {};
staticData.refreshed_at[accountId] = new Date().toISOString();
staticData.expires_at[accountId] = new Date(Date.now() + (response.expires_in || 0) * 1000).toISOString();

return [{
  json: {
    message: `[${accountId}] 토큰 갱신 완료`,
    account_id: accountId,
    new_expires_at: staticData.expires_at[accountId]
  }
}];

const staticData = $getWorkflowStaticData('global');
if (!staticData.posted_products) {
  staticData.posted_products = [];
}

const body = $input.first().json.body || {};
const productUrl = body.product_url || '';
const affiliateLink = body.affiliate_link || '';

function extractProductId(url) {
  if (!url) return null;
  const match = String(url).match(/products\/(\d+)/);
  return match ? match[1] : null;
}

const productId = extractProductId(productUrl) || productUrl || affiliateLink;

if (!productId) {
  throw new Error('product_url 또는 affiliate_link가 없습니다. 웹훅 페이로드를 확인해주세요.');
}

const isDuplicate = staticData.posted_products.indexOf(productId) !== -1;

return [{
  json: {
    is_duplicate: isDuplicate,
    product_id: productId,
    product_title: body.product_title || '',
    product_desc: body.product_desc || '',
    product_url: productUrl,
    affiliate_link: affiliateLink,
    image_url: body.image_url || '',
    price: body.price || '',
    account_id: $input.first().json.account_id || '',
    threads_user_id: $input.first().json.threads_user_id || ''
  }
}];

const staticData = $getWorkflowStaticData('global');
if (!staticData.posted_products) {
  staticData.posted_products = [];
}

let productId;
try {
  productId = $('중복 상품 확인').first().json.product_id;
} catch (e) {
  const productInfo = $('응답 파싱 및 댓글 텍스트 구성').first().json;
  productId = productInfo.affiliate_link;
}

if (productId && staticData.posted_products.indexOf(productId) === -1) {
  staticData.posted_products.push(productId);
}

return [{ json: { recorded_product_id: productId, total_posted_count: staticData.posted_products.length } }];

const rows = $input.all();
const ready = rows.find(r => r.json.affiliate_link && String(r.json.affiliate_link).trim());
return ready ? [ready] : [];

const staticData = $getWorkflowStaticData('global');
const item = $input.first().json;
const accountId = item.account_id || item.threads_user_id || 'default';

if (!staticData.tokens) staticData.tokens = {};

if (!staticData.tokens[accountId] && staticData.access_token) {
  staticData.tokens[accountId] = staticData.access_token;
}

if (!staticData.tokens[accountId]) {
  throw new Error(`[${accountId}] 토큰이 없습니다. n8n에서 이 노드를 대상으로 1회 수동 시딩이 필요합니다 (staticData.tokens.${accountId}).`);
}

return [{ json: { access_token: staticData.tokens[accountId], account_id: accountId } }];

const mediaId = $('media_id 있는 행만 필터링').item.json.media_id;
const insights = $json;
const viewsMetric = (insights.data || []).find(d => d.name === 'views');
const views = viewsMetric && viewsMetric.values && viewsMetric.values[0] ? viewsMetric.values[0].value : null;
return [{ json: { media_id: mediaId, views } }];

