const ACCOUNTS = [
  { account_id: 'acc_general', threads_user_id: '27629464336738548' }
  // 계정 추가 시 이 배열에 { account_id, threads_user_id } 객체만 추가하면 됨 (상품 분류 및 계정 매핑 코드의 ACCOUNT_MAP과 동일하게 유지)
];

return ACCOUNTS.map(a => ({ json: a }));

// 계정 추가 시 이 배열에 { account_id, threads_user_id, keywords } 객체를 추가하세요.
// 예시(비활성, 실제 계정 준비되면 아래 형태로 추가):
// { account_id: 'acc_kitchen', threads_user_id: 'PASTE_ACTUAL_ID', keywords: ['주방', '조리', '냄비', '프라이팬', '청소기'] },
// { account_id: 'acc_camp', threads_user_id: 'PASTE_ACTUAL_ID', keywords: ['캠핑', '텐트', '아웃도어', '등산'] },
const ACCOUNT_MAP = [
  { account_id: 'acc_general', threads_user_id: '27629464336738548', keywords: [] } // fallback, 항상 마지막
];

const body = $input.first().json.body || {};
const text = `${body.product_title || ''} ${body.product_desc || ''}`.toLowerCase();

let matched = ACCOUNT_MAP.find(a =>
  a.keywords.length && a.keywords.some(k => text.includes(k))
);
if (!matched) {
  matched = ACCOUNT_MAP.find(a => a.keywords.length === 0);
}

return [{
  json: {
    ...$input.first().json,
    account_id: matched.account_id,
    threads_user_id: matched.threads_user_id
  }
}];

const staticData = $getWorkflowStaticData('global');
const expiresAt = staticData.expires_at || {};
const tokens = staticData.tokens || {};
const now = Date.now();
const THRESHOLD_DAYS = 7;

const accountIds = Object.keys(tokens);
const alerts = [];

for (const accountId of accountIds) {
  const expiresIso = expiresAt[accountId];
  if (!expiresIso) {
    alerts.push(`- ${accountId}: 갱신 기록 없음 (최초 시딩 후 자동 갱신이 아직 한 번도 안 됨)`);
    continue;
  }
  const daysRemaining = Math.floor((new Date(expiresIso).getTime() - now) / 86400000);
  if (daysRemaining <= THRESHOLD_DAYS) {
    const reason = daysRemaining <= 0 ? '이미 만료됨' : `${daysRemaining}일 후 만료`;
    alerts.push(`- ${accountId}: ${reason} (만료일 ${expiresIso})`);
  }
}

if (alerts.length === 0) {
  return [{ json: { alert: false } }];
}

return [{ json: { alert: true, message: alerts.join('\n') } }];

